def get_path(root, path, default=_UNSET):
    if isinstance(path, str):
        path = path.split('.')
    cur = root
    try:
        for seg in path:
            try:
                cur = cur[seg]
            except (KeyError, IndexError) as exc:
                raise PathAccessError(exc, seg, path)
            except TypeError as exc:
                try:
                    seg = int(seg)
                    cur = cur[seg]
                except (ValueError, KeyError, IndexError, TypeError):
                    if not is_iterable(cur):
                        exc = TypeError('%r object is not indexable'
                                        % type(cur).__name__)
                    raise PathAccessError(exc, seg, path)
    except PathAccessError:
        if default is _UNSET:
            raise
        return default
    return cur

def resolve_path_parts(path_parts):
    ret = []

    for part in path_parts:
        if part == '.':
            pass
        elif part == '..':
            if ret and (len(ret) > 1 or ret[0]):  # prevent unrooting
                ret.pop()
        else:
            ret.append(part)

    if list(path_parts[-1:]) in (['.'], ['..']):
        ret.append('')

    return ret

def index(self, val):
    try:
        return self._get_apparent_index(self.item_index_map[val])
    except KeyError:
        cn = self.__class__.__name__
        raise ValueError(f'{val!r} is not in {cn}')

def augpath(path, suffix='', prefix='', ext=None, base=None, dpath=None,
            multidot=False):
    orig_dpath, fname = split(path)
    if multidot:
        parts = fname.split('.', 1)
        orig_base = parts[0]
        orig_ext = '' if len(parts) == 1 else '.' + parts[1]
    else:
        orig_base, orig_ext = splitext(fname)
    if dpath is None:
        dpath = orig_dpath
    if ext is None:
        ext = orig_ext
    if base is None:
        base = orig_base
    new_fname = ''.join((prefix, base, suffix, ext))
    newpath = join(dpath, new_fname)
    return newpath

def is_iterable(obj):
    try:
        iter(obj)
    except TypeError:
        return False
    return True

